<?php require 'config.php';require_login();$s=$pdo->prepare('SELECT * FROM orders WHERE id=? AND user_id=?');$s->execute([(int)$_GET['id'],$_SESSION['user_id']]);$o=$s->fetch();if(!$o)exit('Order not found');if($_SERVER['REQUEST_METHOD']==='POST'){$pdo->prepare('UPDATE orders SET shipping_name=?,phone=?,address=?,city=?,postal_code=?,delivery_note=? WHERE id=? AND user_id=?')->execute([trim($_POST['shipping_name']),trim($_POST['phone']),trim($_POST['address']),trim($_POST['city']),trim($_POST['postal_code']),trim($_POST['delivery_note']),$o['id'],$_SESSION['user_id']]);header('Location: order.php?id='.$o['id']);exit;}$s=$pdo->prepare('SELECT * FROM order_items WHERE order_id=?');$s->execute([$o['id']]);$items=$s->fetchAll();?><!doctype html><html><head><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="stylesheet" href="style.css"></head><body><div class="wrap"><div class="card"><h1>Order #<?=h($o['id'])?></h1><p>Status: <b><?=h($o['status'])?></b></p><?php foreach($items as $i):?><p><?=h($i['cake_name'])?> · <?=h($i['cake_size'])?> · Qty <?=h($i['quantity'])?> · Message: <?=h($i['message_text'])?></p><?php endforeach;?><h2>Update shipping address</h2><form method="post"><label>Name</label><input name="shipping_name" value="<?=h($o['shipping_name'])?>" required><label>Phone</label><input name="phone" value="<?=h($o['phone'])?>" required><label>Address</label><textarea name="address" required><?=h($o['address'])?></textarea><label>City</label><input name="city" value="<?=h($o['city'])?>" required><label>Postal code</label><input name="postal_code" value="<?=h($o['postal_code'])?>" required><label>Delivery note</label><input name="delivery_note" value="<?=h($o['delivery_note'])?>"><button>Update address</button></form></div></div></body></html>